const body = $input.first().json.body || {};
const headers = $input.first().json.headers || {};
const str = (v) => (typeof v === 'string' ? v.trim() : v == null ? '' : String(v).trim());
const num = (v) => {
  const s = str(v);
  return s === '' ? null : Number(s);
};
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  const v = c === 'x' ? r : (r & 0x3) | 0x8;
  return v.toString(16);
});
const email = str(body.email).toLowerCase();
const phone = str(body.phone).replace(/[^0-9+]/g, '');
const age = num(body.age);
const errors = [];
if (!str(body.first_name)) errors.push('first_name is required');
if (!str(body.last_name)) errors.push('last_name is required');
if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('email is invalid');
if (!phone || phone.length < 7) errors.push('phone is invalid');
if (body.marketing_consent !== true) errors.push('marketing_consent must be true');
if (age === null || Number.isNaN(age) || age < 13 || age > 90) errors.push('age must be between 13 and 90');
const lead = {
  request_id: uuid(),
  lead_id: uuid(),
  submitted_at: new Date().toISOString(),
  status: 'New',
  source: str(body.source) || 'website',
  first_name: str(body.first_name),
  last_name: str(body.last_name),
  phone,
  email,
  age,
  gender: str(body.gender) || null,
  height: num(body.height),
  weight: num(body.weight),
  fitness_goal: str(body.fitness_goal) || null,
  membership_plan: str(body.membership_plan) || null,
  workout_time: str(body.workout_time) || null,
  experience_level: str(body.experience_level) || null,
  medical_conditions: str(body.medical_conditions) || null,
  address: str(body.address) || null,
  city: str(body.city) || null,
  state: str(body.state) || null,
  pincode: str(body.pincode) || null,
  marketing_consent: body.marketing_consent === true,
  notes: str(body.notes) || null,
  ip_address: String(headers['x-forwarded-for'] || headers['x-real-ip'] || '').split(',')[0].trim() || null,
  user_agent: str(headers['user-agent']) || null
};
console.log('[Prepare Lead]', JSON.stringify({ request_id: lead.request_id, email: lead.email, ip: lead.ip_address, errors }));
return [{
  json: {
    valid: errors.length === 0,
    error_code: errors.length ? 'validation' : null,
    errors,
    request_id: lead.request_id,
    lead,
    logs: [{ request_id: lead.request_id, received_at: lead.submitted_at }]
  }
}];

const row = $input.first().json;
const envelope = {
  success: true,
  request_id: row.request_id,
  lead_id: row.lead_id,
  message: 'Application received. A coach will contact you shortly.',
  timestamp: new Date().toISOString()
};
console.log('[Success]', JSON.stringify({ request_id: envelope.request_id, lead_id: envelope.lead_id }));
return [{ json: envelope }];

const input = $input.first().json;
const errText = String(input.error || '').toLowerCase();
let errorCode = input.error_code || 'save_failed';
let message = 'We could not save your application. Please try again.';
if (errorCode === 'validation') {
  message = 'Please fill all required fields correctly and consent to be contacted.';
} else if (/duplicate|23505|already exists/.test(errText)) {
  errorCode = 'duplicate';
  message = 'This email is already registered. Our team will contact you shortly.';
}
const envelope = {
  success: false,
  request_id: input.request_id || $node['Prepare Lead'].json.request_id,
  error_code: errorCode,
  message,
  timestamp: new Date().toISOString()
};
if (errText) envelope.details = errText.slice(0, 300);
console.log('[Error]', JSON.stringify({ request_id: envelope.request_id, error_code: envelope.error_code }));
return [{ json: envelope }];

const lead = $json.lead || $json;
let num = String(lead.phone || '').replace(/[^0-9]/g, '');
if (num.length === 10) num = '91' + num;
else if (num.length === 11 && num.startsWith('0')) num = '91' + num.slice(1);
const names = [lead.first_name, lead.last_name].filter(Boolean).join(' ') || 'there';
const details = [
  'Name: ' + names,
  'Plan selected: ' + (lead.membership_plan || 'not selected'),
  'Fitness goal: ' + (lead.fitness_goal || 'not shared'),
  'Preferred workout time: ' + (lead.workout_time || 'not shared'),
  'Experience level: ' + (lead.experience_level || 'not shared')
].join('\n');
const prompt = 'Write a professional and friendly WhatsApp message (3 to 4 lines, no emojis, no asterisks, no markdown) to ' + names + ', a new gym lead. Encourage and welcome them warmly, briefly mention the plan they selected (' + (lead.membership_plan || 'not yet selected') + '), and close with "Iron Forge Gym". Here are the details:\n' + details;
return [{ json: { number: num, prompt } }];

const candidates = $json.candidates;
const parts = candidates && candidates[0] && candidates[0].content ? candidates[0].content.parts : [];
const text = (parts.map(p => p.text || '').join('')).trim();
return [{ json: { number: $node['Prepare WhatsApp Message'].json.number, text: text || 'Hi! Welcome to Iron Forge Gym. A coach will contact you shortly with your membership details.' } }];
